// Renders release links from assets/downloads.js (generated by
// scripts/add_release.py). Pages declare placeholders:
//
//   <ul data-download-list></ul>                 compact list of all releases
//   <div data-downloads="all"></div>             full cards, all releases
//   <div data-downloads="tf2-aimbot"></div>      full card, one release
//   <div data-download-button="tf2-aimbot" data-label="..."></div>
//   <span data-download-hash="tf2-aimbot"></span>
//   <p data-repo-link>...</p>                    shown only if config.js sets SITE.repo
//   <span data-site-title></span> <span data-year></span>
//
// Every download is a GitHub Release asset: the link is built from SITE.repo
// (assets/config.js) + the entry's tag + asset name. With SITE.repo empty the
// cards still render their metadata but say what needs configuring instead of
// linking to a 404.
(function () {
  "use strict";

  var script = document.currentScript;
  var src = (script && script.getAttribute("src")) || "";
  var ROOT = src.replace(/assets\/site\.js.*$/, "");

  var cfg = (typeof SITE !== "undefined") ? SITE : {};
  var data = (typeof DOWNLOADS !== "undefined" && Array.isArray(DOWNLOADS)) ? DOWNLOADS : [];
  var byId = function (id) { return data.filter(function (d) { return d.id === id; })[0]; };

  // Which repo hosts the releases? SITE.repo wins if set; otherwise derive it
  // from where the page is served (on GitHub Pages the answer is in the URL):
  //   <user>.github.io/<repo>/... -> <user>/<repo>
  //   <user>.github.io/...        -> <user>/<user>.github.io   (user site)
  //   custom domain / file:// / localhost -> "" (must set SITE.repo)
  function repoFor(loc) {
    loc = loc || window.location;
    var host = (loc.hostname || "");
    if (!/\.github\.io$/i.test(host) || loc.protocol === "file:") return "";
    var user = host.replace(/\.github\.io$/i, "");
    if (!user) return "";
    var first = (loc.pathname || "").split("/").filter(Boolean)[0] || "";
    if (!first || /\.html?$/i.test(first)) return user + "/" + user + ".github.io";
    return user + "/" + first;
  }

  var repo = ((cfg.repo || "").trim() || repoFor()).replace(/^\/+|\/+$/g, "");

  function fmtSize(b) {
    return b >= 1048576 ? (b / 1048576).toFixed(2) + " MB" : Math.round(b / 1024) + " KB";
  }
  function ghBase() { return "https://github.com/" + repo; }
  function assetUrl(d) { return repo ? ghBase() + "/releases/download/" + d.tag + "/" + d.asset : null; }
  function tagUrl(d) { return repo ? ghBase() + "/releases/tag/" + d.tag : null; }

  function el(tag, cls, text) {
    var n = document.createElement(tag);
    if (cls) n.className = cls;
    if (text != null) n.textContent = text;
    return n;
  }
  function link(href, cls, text) {
    var a = el("a", cls, text);
    a.href = href;
    return a;
  }
  function unconfigured() {
    return el("span", "muted",
      "下载地址未配置:请在 assets/config.js 里把 SITE.repo 填成「用户名/仓库名」");
  }

  function copyButton(text) {
    var b = el("button", "copy", "复制");
    b.type = "button";
    b.addEventListener("click", function () {
      var done = function (ok) {
        b.textContent = ok ? "已复制" : "复制失败";
        setTimeout(function () { b.textContent = "复制"; }, 1500);
      };
      if (navigator.clipboard && navigator.clipboard.writeText) {
        navigator.clipboard.writeText(text).then(function () { done(true); },
                                                 function () { done(false); });
      } else {
        done(false);
      }
    });
    return b;
  }

  function metaList(d) {
    var dl = el("dl", "kv");
    var add = function (key, node) { dl.appendChild(el("dt", null, key)); dl.appendChild(node); };

    add("版本", el("dd", null, d.version + "(" + d.date + ")"));
    add("适用游戏", el("dd", null, d.gameVersion));
    add("Release 资产", el("dd", null, d.asset + " · " + fmtSize(d.size)));

    var hash = el("dd");
    hash.appendChild(el("span", "hash", d.sha256));
    hash.appendChild(document.createTextNode(" "));
    hash.appendChild(copyButton(d.sha256));
    add("SHA256", hash);

    return dl;
  }

  function card(d) {
    var c = el("div", "dl-card");
    c.appendChild(el("h3", null, d.name));
    c.appendChild(el("p", "sub", d.game + " · " + d.scope + " · 版本 " + d.version + " · " + d.date));
    c.appendChild(el("p", "summary", d.summary));

    if (d.notes && d.notes.length) {
      var notes = el("ul", "notes");
      d.notes.forEach(function (n) { notes.appendChild(el("li", null, n)); });
      c.appendChild(notes);
    }

    c.appendChild(metaList(d));

    var actions = el("div", "actions");
    var url = assetUrl(d);
    if (url) {
      actions.appendChild(link(url, "btn", "下载 " + d.asset));
      actions.appendChild(link(tagUrl(d), "btn ghost", "Release 页面 →"));
    } else {
      actions.appendChild(unconfigured());
    }
    if (d.guide) actions.appendChild(link(ROOT + d.guide, "btn ghost", "使用说明 →"));
    c.appendChild(actions);

    if (d.tags && d.tags.length) {
      var tags = el("div", "tags");
      d.tags.forEach(function (t) { tags.appendChild(el("span", "tag", t)); });
      c.appendChild(tags);
    }
    return c;
  }

  function listItem(d) {
    var li = el("li");
    var url = assetUrl(d);
    if (url) {
      li.appendChild(link(url, "title", d.name));
    } else {
      var strong = el("strong", "title", d.name);
      li.appendChild(strong);
    }
    li.appendChild(el("span", "date", d.version + " · " + fmtSize(d.size)));
    li.appendChild(el("p", null, d.summary));
    var more = el("p");
    if (url) more.appendChild(link(tagUrl(d), null, "Release 页面 →"));
    if (d.guide) {
      if (url) more.appendChild(document.createTextNode("　"));
      more.appendChild(link(ROOT + d.guide, null, "使用说明 →"));
    }
    more.appendChild(document.createTextNode("　"));
    more.appendChild(link(ROOT + "projects.html", null, "校验值与要求 →"));
    li.appendChild(more);
    if (!url) li.appendChild(el("p", "muted", unconfigured().textContent));
    return li;
  }

  function render() {
    document.querySelectorAll("[data-download-list]").forEach(function (node) {
      if (!data.length) {
        node.appendChild(el("li", "muted", "暂无下载。"));
        return;
      }
      data.forEach(function (d) { node.appendChild(listItem(d)); });
    });

    document.querySelectorAll("[data-downloads]").forEach(function (node) {
      var want = node.getAttribute("data-downloads");
      var list = (!want || want === "all") ? data : data.filter(function (d) { return d.id === want; });
      if (!list.length) {
        node.appendChild(el("p", "muted", want === "all" ? "暂无下载。" : "该项目的下载还没放上来。"));
        return;
      }
      list.forEach(function (d) { node.appendChild(card(d)); });
    });

    document.querySelectorAll("[data-download-button]").forEach(function (node) {
      var d = byId(node.getAttribute("data-download-button"));
      if (!d) { node.parentNode.removeChild(node); return; }
      var url = assetUrl(d);
      if (url) {
        node.appendChild(link(url, "btn", node.getAttribute("data-label") || ("下载 " + d.asset)));
        node.appendChild(el("span", "muted", d.asset + " · " + fmtSize(d.size)));
        node.appendChild(link(tagUrl(d), "btn ghost", "Release 页面 →"));
      } else {
        node.appendChild(unconfigured());
      }
    });

    document.querySelectorAll("[data-download-hash]").forEach(function (node) {
      var d = byId(node.getAttribute("data-download-hash"));
      if (d) node.appendChild(el("code", "hash", d.sha256));
    });

    document.querySelectorAll("[data-site-title]").forEach(function (node) {
      if (cfg.title) node.textContent = cfg.title;
    });
    document.querySelectorAll("[data-year]").forEach(function (node) {
      node.textContent = String(new Date().getFullYear());
    });

    document.querySelectorAll("[data-repo-link]").forEach(function (node) {
      if (!repo) { node.parentNode.removeChild(node); return; }
      node.appendChild(link(ghBase(), null, "GitHub 仓库(有问题在这里提)"));
    });
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", render);
  } else {
    render();
  }

  // Exposed so the config self-test (and anyone curious) can check the
  // derivation without needing to be served from github.io.
  window.__blog = { repoFor: repoFor, repo: repo, downloads: data };
})();
